import { useEffect, useRef, useState } from 'react'
import {
  ArrowDown,
  Check,
  CircleAlert,
  LoaderCircle,
  Square,
} from 'lucide-react'
import Markdown, { type Components } from 'react-markdown'
import { AppHeader } from '@/components/app-header'
import { Button } from '@/components/ui/button'
import type { AnalysisStream } from '@/features/privacy-stream/use-analysis-stream'
import { analysisMarkdownOptions } from '@/features/privacy-stream/markdown-options'

// Descendant utilities also style elements generated by Markdown and GFM.
const markdownClassName = [
  'min-h-[128px] pt-[24px] first:pt-0 text-[17px] leading-[1.95] wrap-anywhere text-ink-secondary [@media(max-width:45rem)]:text-[16px]',
  '[&>:first-child]:mt-0 [&>:last-child]:mb-0 [&>:is(h1,h2):first-child]:border-t-0 [&>:is(h1,h2):first-child]:pt-0',
  '[&_p]:my-[16px]',
  '[&_:is(h1,h2,h3)]:scroll-mt-[24px] [&_:is(h1,h2,h3)]:font-semibold [&_:is(h1,h2,h3)]:leading-[1.6] [&_:is(h1,h2,h3)]:tracking-[-0.035em] [&_:is(h1,h2,h3)]:break-keep [&_:is(h1,h2,h3)]:text-foreground',
  '[&_:is(h1,h2)]:mt-[40px] [&_:is(h1,h2)]:mb-[16px] [&_:is(h1,h2)]:border-t [&_:is(h1,h2)]:border-border [&_:is(h1,h2)]:pt-[40px] [&_:is(h1,h2)]:text-[23px]',
  '[@media(max-width:45rem)]:[&_:is(h1,h2)]:mt-[28px] [@media(max-width:45rem)]:[&_:is(h1,h2)]:pt-[28px] [@media(max-width:45rem)]:[&_:is(h1,h2)]:text-[21px]',
  '[&_h3]:mt-[24px] [&_h3]:text-[19px] [&_strong]:font-semibold [&_strong]:text-foreground',
  '[&_blockquote]:my-[24px] [&_blockquote]:border-l-2 [&_blockquote]:border-cool [&_blockquote]:py-[4px] [&_blockquote]:pl-[24px] [&_blockquote]:text-[16px] [&_blockquote]:text-ink-secondary [&_blockquote_p]:my-[8px] [@media(max-width:45rem)]:[&_blockquote]:pl-[16px] [@media(max-width:45rem)]:[&_blockquote]:text-[15px]',
  '[&_:is(ul,ol)]:my-[16px] [&_:is(ul,ol)]:pl-[24px] [&_ul]:list-disc [&_ol]:list-decimal [&_li]:my-[8px] [&_li]:pl-[4px] [&_li::marker]:text-muted-foreground',
  '[&_a]:text-cool [&_a]:underline [&_a]:decoration-1 [&_a]:underline-offset-4 [&_a:hover]:text-foreground',
  '[&_img]:my-[24px] [&_img]:block [&_img]:h-auto [&_img]:max-h-[420px] [&_img]:w-full [&_img]:rounded-input [&_img]:border [&_img]:border-border [&_img]:object-contain [@media(max-width:45rem)]:[&_img]:max-h-[320px]',
  '[&_pre]:max-w-full [&_pre]:overflow-x-auto [&_pre]:rounded-input [&_pre]:bg-secondary [&_pre]:p-[16px] [&_pre]:text-[14px] [&_code]:font-code [&_code]:text-[0.88em] [&_:not(pre)>code]:rounded-[4px] [&_:not(pre)>code]:bg-secondary [&_:not(pre)>code]:px-[5px] [&_:not(pre)>code]:py-[2px] [&_pre_code]:text-[length:inherit]',
  '[&_.contains-task-list]:list-none [&_.contains-task-list]:pl-0 [&_.task-list-item_input]:mr-[8px] [&_.task-list-item_input]:accent-primary',
  '[&_hr]:my-[40px] [&_hr]:border-0 [&_hr]:border-t [&_hr]:border-border',
].join(' ')

const markdownComponents: Components = {
  ...analysisMarkdownOptions.components,
  img: ({ src, alt }) => <img src={src} alt={alt ?? ''} loading="lazy" />,
  table: ({ children }) => (
    <div
      className="my-[24px] max-w-full overflow-x-auto rounded-input border border-border [&_table]:w-full [&_table]:min-w-[32rem] [&_table]:border-collapse [&_table]:text-[14px] [&_table]:leading-[1.8] [&_:is(th,td)]:min-w-[8rem] [&_:is(th,td)]:border-b [&_:is(th,td)]:border-border [&_:is(th,td)]:px-[16px] [&_:is(th,td)]:py-[12px] [&_:is(th,td)]:text-left [&_:is(th,td)]:align-top [&_th]:bg-card [&_th]:font-semibold [&_th]:text-foreground [&_tbody_tr:last-child_td]:border-b-0"
      role="region"
      aria-label="분석 결과 표"
      tabIndex={0}
    >
      <table>{children}</table>
    </div>
  ),
}

function StreamingPage({ stream }: { stream: AnalysisStream }) {
  const handle = stream.handle
  const [awayFromBottom, setAwayFromBottom] = useState(false)
  const followTail = useRef(true)
  const progressRef = useRef<HTMLElement>(null)
  const isStreaming = stream.status === 'streaming'
  const isReceiving = isStreaming || stream.status === 'connecting'
  const isComplete = stream.status === 'complete'

  useEffect(() => {
    const handleScroll = () => {
      const nearBottom =
        document.documentElement.scrollHeight -
          window.scrollY -
          window.innerHeight <
        160
      followTail.current = nearBottom
      setAwayFromBottom(!nearBottom)
    }
    window.addEventListener('scroll', handleScroll, { passive: true })
    return () => window.removeEventListener('scroll', handleScroll)
  }, [])

  useEffect(() => {
    if (followTail.current) {
      window.scrollTo({
        top: document.documentElement.scrollHeight,
        behavior: 'instant',
      })
    }
  }, [stream.visibleText, stream.stages])

  function jumpToLatest() {
    followTail.current = true
    setAwayFromBottom(false)
    window.scrollTo({
      top: document.documentElement.scrollHeight,
      behavior: 'instant',
    })
  }

  function jumpToProgress() {
    followTail.current = false
    setAwayFromBottom(true)
    progressRef.current?.focus({ preventScroll: true })
    progressRef.current?.scrollIntoView({ block: 'start', behavior: 'instant' })
  }

  return (
    <>
      <a
        className="absolute top-[16px] left-[16px] z-500 -translate-y-[200%] rounded-input bg-primary px-[24px] py-[12px] text-primary-foreground focus-visible:translate-y-0"
        href="#stream-main"
      >
        본문으로 이동
      </a>
      <AppHeader />
      <main
        id="stream-main"
        className="mx-auto min-h-[calc(100dvh-73px)] w-full max-w-[880px] px-[40px] py-[56px] data-[receiving=true]:pb-[190px] [@media(max-width:45rem)]:min-h-[calc(100dvh-65px)] [@media(max-width:45rem)]:px-[20px] [@media(max-width:45rem)]:py-[32px] [@media(max-width:45rem)]:data-[receiving=true]:pb-[210px]"
        data-receiving={isReceiving}
      >
        <header>
          <div className="flex flex-wrap items-center gap-[12px] text-[14px] text-ink-secondary">
            <span>@{handle}</span>
          </div>
          <h1 className="mt-[24px] max-w-[700px] text-[clamp(26px,3vw,36px)] font-semibold leading-[1.5] tracking-[-0.045em] break-keep [@media(max-width:45rem)]:mt-[16px] [@media(max-width:45rem)]:text-[27px]">
            공개된 일상 속, 개인정보의 단서를 살펴볼게요
          </h1>
        </header>

        <section
          className="mt-[40px] min-h-[220px] rounded-card border border-border bg-card px-[32px] py-[28px] [@media(max-width:45rem)]:mt-[24px] [@media(max-width:45rem)]:px-[16px] [@media(max-width:45rem)]:py-[24px]"
          aria-label="분석 답변"
        >
          {stream.stages.length > 0 ? (
            <section
              ref={progressRef}
              id="analysis-progress"
              className="mt-[24px] rounded-input border border-border bg-card p-[16px] text-[12px] text-ink-secondary first:mt-0"
              aria-label="분석 진행 상황"
              tabIndex={-1}
            >
              <h2 className="mb-[12px] font-medium text-muted-foreground">
                분석 진행 상황
              </h2>
              <ul className="grid gap-[8px]">
                {stream.stages.map((stage) => (
                  <li
                    key={stage.id}
                    data-state={stage.state}
                    className="group/stage flex items-start gap-[8px] leading-[1.8] wrap-anywhere [&_svg]:mt-[4px] [&_svg]:shrink-0 [&_svg]:text-primary data-[state=error]:[&_svg]:text-destructive data-[state=done]:[&_svg]:text-success"
                  >
                    {stage.state === 'running' && isReceiving ? (
                      <LoaderCircle
                        size={14}
                        className="animate-spin motion-reduce:animate-none"
                        aria-hidden="true"
                      />
                    ) : stage.state === 'done' ? (
                      <Check size={14} aria-hidden="true" />
                    ) : stage.state === 'error' ? (
                      <CircleAlert size={14} aria-hidden="true" />
                    ) : (
                      <Square size={12} aria-hidden="true" />
                    )}
                    <span className="min-w-0 flex-1">{stage.text}</span>
                    <span className="shrink-0 whitespace-nowrap text-muted-foreground group-data-[state=error]/stage:text-destructive">
                      {stage.state === 'done'
                        ? '완료'
                        : stage.state === 'error'
                          ? '실패'
                          : isReceiving
                            ? '진행 중'
                            : '중단됨'}
                    </span>
                  </li>
                ))}
              </ul>
            </section>
          ) : null}

          <article
            className={markdownClassName}
            aria-label="개인정보 노출 분석 답변"
            aria-busy={isReceiving}
          >
            <Markdown
              {...analysisMarkdownOptions}
              components={markdownComponents}
            >
              {stream.visibleText}
            </Markdown>
            {!stream.visibleText && isReceiving ? (
              <div
                className="grid gap-[12px] py-[8px] [&_span]:h-[12px] [&_span]:w-[90%] [&_span]:rounded-input [&_span]:bg-border [&_span:last-child]:w-[55%]"
                aria-hidden="true"
              >
                <span />
                <span />
                <span />
              </div>
            ) : null}
          </article>

          {stream.status === 'error' || stream.status === 'stopped' ? (
            <div
              className="mt-[24px] rounded-input border border-border bg-card p-[16px] text-[14px] leading-[1.8] wrap-anywhere text-ink-secondary [&_p+p]:mt-[12px]"
              role="alert"
            >
              <p>
                {stream.error ||
                  '수신을 중지했어요. 지금까지 받은 답변은 유지됩니다.'}
              </p>
              <p>
                새 분석은 상단 꼬리표 로고를 눌러 시작할 수 있어요.
                새로고침하거나 화면을 나가면 이 답변을 복원할 수 없어요.
              </p>
            </div>
          ) : null}

          <p className="sr-only" role="status">
            {isComplete ? '분석 답변이 도착했어요.' : ''}
          </p>
        </section>
        {isReceiving ? (
          <div className="fixed inset-x-0 bottom-0 z-10 mx-auto w-[min(100%-80px,800px)] bg-background pt-[12px] pb-[max(16px,env(safe-area-inset-bottom))] [@media(max-width:45rem)]:w-[calc(100%-32px)]">
            {awayFromBottom ? (
              <Button
                type="button"
                variant="outline"
                className="mx-auto mb-[12px] flex min-h-[44px] w-fit rounded-[22px] bg-card text-[12px] leading-(--text-sm--line-height) text-foreground transition-colors hover:bg-card"
                onClick={jumpToLatest}
              >
                <ArrowDown size={14} aria-hidden="true" />
                최근 답변으로
              </Button>
            ) : null}
            <div className="flex min-h-[68px] items-center justify-between gap-[16px] rounded-[12px] border border-border bg-card px-[16px] py-[12px] [@media(max-width:45rem)]:gap-[8px] [@media(max-width:45rem)]:px-[12px] [@media(max-width:45rem)]:py-[8px]">
              <div
                className="flex min-w-0 items-center gap-[8px] text-[14px] leading-[1.7] break-keep text-ink-secondary [&>svg]:text-primary [@media(max-width:45rem)]:text-[12px]"
                role="status"
                aria-live="polite"
              >
                <LoaderCircle
                  className="animate-spin motion-reduce:animate-none"
                  size={16}
                  aria-hidden="true"
                />
                <div className="min-w-0">
                  <span className="line-clamp-2 wrap-anywhere">
                    {isStreaming
                      ? stream.progressText ||
                        (stream.visibleText
                          ? '분석 답변을 작성하고 있어요'
                          : '분석 정보를 확인하고 있어요')
                      : '분석 답변에 연결하고 있어요'}
                  </span>
                  {stream.stages.length > 0 ? (
                    <Button
                      type="button"
                      variant="ghost"
                      className="inline-flex min-h-[32px] items-center text-[12px] leading-(--text-sm--line-height) text-cool underline underline-offset-[3px] hover:text-cool"
                      aria-controls="analysis-progress"
                      onClick={jumpToProgress}
                    >
                      진행 내역 보기
                    </Button>
                  ) : null}
                </div>
              </div>
              <Button
                type="button"
                variant="outline"
                className="min-h-[44px] shrink-0 text-[12px] leading-(--text-sm--line-height) transition-colors"
                onClick={stream.stop}
              >
                <Square size={13} aria-hidden="true" />
                수신 중지
              </Button>
            </div>
          </div>
        ) : null}
      </main>
    </>
  )
}

export default StreamingPage
